,'admin','admin','123456/**/and/**/3=DBMS_PIPE.RECEIVE_MESSAGE(\'s\',0)','2023-12-03 14:03:16','2023-12-03 14:03:16'),(840,13,'expr 985926627 + 854781121','admin','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(841,13,'<%- 957528924+849842266 %>','admin','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(842,13,'admin','admin\'/**/and(select\'1\'from/**/pg_sleep(0))::text>\'0','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(843,10,'admin','admin\"and/**/extractvalue(1,concat(char(126),md5(1090917470)))and\"','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(844,6,'admin\'/**/and(select\'1\'from/**/pg_sleep(0))::text>\'0','admin','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(845,11,'admin\'and(select\'1\'from/**/cast(md5(1491674649)as/**/int))>\'0','admin','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(846,6,'expr 965811918 + 848472430','admin','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(847,6,'admin','<%- 925625943+845763936 %>','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(848,13,'admin','admin\'and(select\'1\'from/**/cast(md5(1195640062)as/**/int))>\'0','123456','2023-12-03 14:03:16','2023-12-03 14:03:16'),(849,19,'admin','admin','123456/**/and/**/3=DBMS_PIPE.RECEIVE_MESSAGE(\'z\',2)','2023-12-03 14:03:16','2023-12-03 14:03:16'),(850,11,'admin','admin','123456\"and\"i\"=\"d','2023-12-03 14:03:17','2023-12-03 14:03:17'),(851,16,'admin','admin','123456鎈\'\"\\(','2023-12-03 14:03:17','2023-12-03 14:03:17'),(852,15,'admin','admin','123456/**/and/**/2=DBMS_PIPE.RECEIVE_MESSAGE(\'m\',2)','2023-12-03 14:03:17','2023-12-03 14:03:17'),(853,10,'admin','extractvalue(1,concat(char(126),md5(1355978956)))','123456','2023-12-03 14:03:17','2023-12-03 14:03:17'),(854,11,'admin/**/and/**/cast(md5(\'1109014644\')as/**/int)>0','admin','123456','2023-12-03 14:03:17','2023-12-03 14:03:17'),(855,6,'admin\'/**/and(select\'1\'from/**/pg_sleep(2))::text>\'0','admin','123456','2023-12-03 14:03:17','2023-12-03 14:03:17'),(856,13,'ad