--
-- Table structure for table `contacts`
--

DROP TABLE IF EXISTS `contacts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `contacts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` bigint(20) NOT NULL,
  `owner_type` varchar(20) NOT NULL,
  `type` enum('Creator','Brand') NOT NULL DEFAULT 'Brand',
  `name` varchar(255) DEFAULT '',
  `email` varchar(255) DEFAULT NULL,
  `website` varchar(255) NOT NULL,
  `domain` varchar(255) NOT NULL,
  `logo` varchar(255) DEFAULT NULL,
  `network_id` int(11) DEFAULT NULL,
  `network` varchar(255) DEFAULT NULL,
  `network_link` varchar(255) DEFAULT NULL,
  `tags` varchar(255) DEFAULT NULL,
  `commission` float DEFAULT NULL,
  `commission_type` varchar(1) DEFAULT NULL,
  `commission_unit` varchar(255) DEFAULT NULL,
  `exclusive_deal` varchar(255) DEFAULT NULL,
  `code` varchar(8) DEFAULT NULL,
  `offers` tinyint(1) NOT NULL DEFAULT 0,
  `posts` tinyint(1) NOT NULL DEFAULT 0,
  `featured` tinyint(1) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=177 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

